function result(q, answer, unit, hint, solution, wrong, feedback) {
  const rounded = n => Math.round(n * 100) / 100;
  const target = rounded(answer);
  return {q, answer: target, unit, hint, solution, wrong: rounded(wrong) === target ? null : rounded(wrong), feedback};
}
const n = (s, mod, offset = 0) => Math.abs(Math.trunc(s)) % mod + offset;
export const course = {
 title:'R1', intro:'Matematikk R1 utforsker funksjoner, grenseverdier, derivasjon, modeller og vektorer. Arbeid med begrunnelser, representasjoner og reelle data; et tall alene er sjelden hele svaret.', source:'https://www.udir.no/lk20/mat03-02/kompetansemaal-og-vurdering/kv293?lang=nob', chapters:[
 {id:'grenser',title:'Grenseverdier og kontinuitet',summary:'Undersøk hva funksjoner nærmer seg, og begrunn kontinuitet.',
 theory:['Grenseverdien lim(x→a) f(x) = L betyr at funksjonsverdiene ligger vilkårlig nær L når x ligger tilstrekkelig nær a, med x ≠ a. Venstre- og høyregrense må være like for at en tosidig grense skal eksistere.','f er kontinuerlig i a når f(a) er definert og lim(x→a) f(x) = f(a). Faktorisering, tabell og graf er ulike strategier; numeriske verdier kan støtte, men ikke alene bevise en grense. Trappefunksjoner kan modellere diskontinuerlige takster.'],
 example:['For f(x)=(x²−4)/(x−2), x ≠ 2, gir faktorisering f(x)=x+2. Dermed er grensen 4 når x→2, selv om f(2) ikke er definert.','Definerer vi f(2)=4, blir funksjonen kontinuerlig der. Velger vi f(2)=5, er diskontinuiteten hevbar.'],
 activity:'Undersøk f(x)=(x²−9)/(x−3), x≠3, numerisk, grafisk og algebraisk. Foreslå en verdi for f(3) som gir kontinuitet. Tolk dessuten brøken som gjennomsnittlig vekstfart for g(x)=x² fra 3 til x, og forklar hva grensen gir i denne tolkningen. Konstruer også en diskontinuerlig prisfunksjon med sprang og forklar hva spranget betyr.',criteria:['Sammenligner tre metoder og begrunner grenseverdien.','Skiller mellom grenseverdi og funksjonsverdi.','Begrunner kontinuitet og tolker en diskontinuerlig modell.'],model:'For x≠3 er f(x)=x+3, så grensen er 6. Tabellen nær 3 støtter resultatet. Verdien f(3)=6 gir kontinuitet. Som differansekvotient går uttrykket mot den momentane vekstfarten g′(3)=6. En takst som er 50 kr til og med 1 kg og 80 kr over 1 kg har et sprang ved 1 kg.',teacher:'Spør om en grense kan eksistere uten at funksjonen er definert i punktet. Bruk ensidige grenser ved sprang.',goals:['Utforske og bestemme grenseverdier og argumentere for anvendelser.','Begrunne kontinuitet eller diskontinuitet og gi anvendelser.'],
 task(level,seed){let a=n(seed,8,2);if(level===0)return result(`Finn grensen når x → ${a} for f(x) = 2x + 1.`,2*a+1,'','Bruk kontinuiteten til polynomer.',`2 · ${a} + 1 = ${2*a+1}.`,2*a,'Husk konstantleddet.');if(level===1)return result(`Finn lim(x→${a}) (x² − ${a*a})/(x − ${a}).`,2*a,'','Faktoriser telleren før du tar grensen.',`(x² − ${a*a})/(x − ${a}) = x + ${a} når x ≠ ${a}; grensen er ${2*a}.`,a,'Grenseverdien er summen av begge leddene.');return result(`La f(x) = (x² − ${a*a})/(x − ${a}) for x ≠ ${a} og f(${a}) = c. Hvilken c gir kontinuitet?`,2*a,'','Finn grensen og sett c lik denne.',`Grensen er ${a} + ${a} = ${2*a}; kontinuitet krever c = ${2*a}.`,a*a,'Funksjonsverdien må være lik grenseverdien.');}},
 {id:'derivert',title:'Derivasjon fra definisjonen',summary:'Koble momentan vekstfart, sekant og tangent.',
 theory:['Gjennomsnittlig vekstfart på [a,a+h] er (f(a+h)−f(a))/h. Når denne differansekvotienten har en endelig grense når h→0, er grensen f′(a), stigningstallet til tangenten.','En funksjon som er deriverbar i et punkt, er kontinuerlig der. Det omvendte gjelder ikke: f(x)=|x| har en knekk i 0 og ulik venstre- og høyrederivert. Numerisk differanse kan påvirkes av avrunding når h er svært liten.'],example:['For f(x)=x² ved x=2 er differansekvotienten ((2+h)²−4)/h = 4+h.','Grensen er 4, så tangenten er y−4=4(x−2).'],activity:'Bruk f(x)=x² ved x=3. Finn den deriverte med differansekvotient, tegn sekant og tangent, og lag en tabell med h=1, 0,1 og 0,01. Undersøk deretter hvorfor |x| ikke er deriverbar i 0.',criteria:['Finner samme derivert algebraisk, geometrisk og numerisk.','Tolker momentan vekstfart.','Begrunner manglende deriverbarhet med ensidige stigningstall.'],model:'(f(3+h)−f(3))/h=6+h, som nærmer seg 6. Sekantstigningene er 7, 6,1 og 6,01; tangenten har stigning 6. For |x| er venstrederivert −1 og høyrederivert 1.',teacher:'Skill mellom gjennomsnittsfart på et intervall og momentan fart. Spør hvorfor h ikke kan være 0 før grenseprosessen.',goals:['Forstå vekstfart, grenseverdi og derivasjon i praktiske problemer.','Bestemme derivert geometrisk, algebraisk og numerisk og gi eksempler på ikke-deriverbarhet.'],
 task(level,seed){let a=n(seed,7,2);if(level===0)return result(`f(x)=x². Finn gjennomsnittlig vekstfart fra x=${a} til x=${a+1}.`,2*a+1,'','Bruk differansen i funksjonsverdi delt på differansen i x.',`((${a+1})²−${a}²)/1 = ${2*a+1}.`,2*a,'Dette er momentan vekstfart ved startpunktet.');if(level===1)return result(`f(x)=x². Finn f′(${a}).`,2*a,'','Bruk grensen til differansekvotienten.',`(( ${a}+h )²−${a*a})/h = ${2*a}+h → ${2*a}.`,a*a,'Dette er funksjonsverdien.');return result(`For f(x)=x², finn konstantleddet i tangenten ved x=${a}, skrevet y=mx+b.`,-a*a,'','Finn stigningstall og sett inn punktet.',`m=${2*a}; ${a*a}=${2*a}·${a}+b gir b=${-a*a}.`,a*a,'Tangenten går gjennom punktet, men konstantleddet er ikke punktets y-verdi.');}},
 {id:'analyse',title:'Derivasjon og funksjonsanalyse',summary:'Analyser vekst, ekstremalpunkter og optimering.',
 theory:['Potensregelen gir (xⁿ)′=nxⁿ⁻¹ der uttrykkene er definert. Produktregelen er (uv)′=u′v+uv′ og kjerneregelen (f(g(x)))′=f′(g(x))g′(x). Fortegnet til f′ beskriver hvor funksjonen vokser og avtar.','Stasjonære punkter oppfyller f′=0, men trenger ikke være ekstremalpunkter. Ved optimering på et lukket intervall må både kritiske punkter og endepunkter vurderes. En derivert i en modell har enhet avhengig størrelse per uavhengig størrelse.'],example:['f(x)=−x²+6x på [0,8] har f′(x)=−2x+6, med kritisk punkt x=3.','f(0)=0, f(3)=9 og f(8)=−16; maksimum er 9 ved x=3.'],activity:'Et rektangel har omkrets 24 cm. Undersøk hvilket areal som er størst ved å uttrykke arealet som funksjon av én side. Deriver, analyser fortegn og kontroller randverdiene. Forklar hvorfor modellen har sitt aktuelle definisjonsintervall.',criteria:['Definerer variabel og gyldig intervall.','Deriverer korrekt og undersøker kritiske punkter og randverdier.','Tolker og begrunner maksimum i konteksten.'],model:'Sett sidene x og 12−x, der 0≤x≤12. A=x(12−x), A′=12−2x. A′ skifter fra positiv til negativ ved x=6. Endepunktene gir 0, mens A(6)=36 cm²: et kvadrat er størst.',teacher:'Et nullpunkt for den deriverte er ikke automatisk et toppunkt. La elevene kontrollere med fortegn og endepunkter.',goals:['Analysere og tolke funksjoner ved derivasjon.','Bruke derivasjon og vekstfart i praktiske problemer.'],
 task(level,seed){let a=n(seed,6,2),x=n(seed,5,1);if(level===0)return result(`f(x)=${a}x². Finn f′(${x}).`,2*a*x,'','Deriver med potensregelen og sett inn x.',`f′(x)=${2*a}x, så f′(${x})=${2*a*x}.`,a*x*x,'Dette er funksjonsverdien.');if(level===1)return result(`f(x)=−x²+${2*a}x. Finn x-koordinaten til toppunktet.`,a,'','Sett den deriverte lik null.',`f′(x)=−2x+${2*a}=0 gir x=${a}; fortegnet skifter fra positivt til negativt.`,2*a,'Denne verdien er ikke løsningen på f′(x)=0.');return result(`f(x)=(x²+1)². Finn f′(${x}).`,4*x*(x*x+1),'','Bruk kjerneregelen.',`f′(x)=2(x²+1)·2x; f′(${x})=${4*x*(x*x+1)}.`,2*(x*x+1),'Multipliser også med den deriverte av den indre funksjonen.');}},
 {id:'logaritmer',title:'Potenser, logaritmer og likninger',summary:'Bruk logaritmer og potensregler til å løse likninger.',
 theory:['For positive grunntall kan vi bruke aᵘaᵛ=aᵘ⁺ᵛ og (aᵘ)ᵛ=aᵘᵛ. For positive a og b gjelder ln(ab)=ln a+ln b, ln(a/b)=ln a−ln b og ln(aʳ)=r ln a. Logaritmen er bare definert for positivt argument. Reglene følger av sammenhengen mellom eksponentialfunksjon og logaritme.','Eksponentiallikninger kan løses ved felles grunntall eller logaritmer. I logaritmelikninger må løsninger kontrolleres mot definisjonsmengden. ln(a+b) er generelt ikke lik ln a + ln b.'],example:['2ˣ=7 gir x=ln 7/ln 2 ≈ 2,81. Kontroll: 2²·⁸¹ ≈ 7.','ln(x−1)=ln 3 gir x−1=3 og x=4, som oppfyller x>1.'],activity:'Sammenlign metodene felles grunntall, grafisk løsning og logaritmer for 4ˣ=8. Undersøk så ln(x−1)+ln(x+1)=ln 8 og kontroller definisjonsmengden og alle foreslåtte løsninger.',criteria:['Bruker og begrunner logaritmeregler.','Sammenligner løsningsstrategier.','Kontrollerer definisjonsmengde og løsninger.'],model:'4ˣ=8 gir 2²ˣ=2³, altså x=1,5. Også ln 8/ln 4=1,5. For logaritmelikningen er x>1 og ln(x²−1)=ln 8, altså x²=9. Bare x=3 er tillatt.',teacher:'Elevene må kontrollere argumentene i hver logaritme, ikke bare produktet etter sammenslåing.',goals:['Utforske potens- og logaritmeregler og løse eksponential- og logaritmelikninger med ulike strategier.'],
 task(level,seed){let a=n(seed,6,2),x=n(seed,4,2);if(level===0)return result(`Løs ${a}^x = ${a**x}. Finn x.`,x,'','Skriv begge sider med samme grunntall.',`${a}^${x}=${a**x}, så x=${x}.`,a,'Grunntallet er ikke eksponenten.');if(level===1)return result(`Løs ln(x) = ln(${a}). Finn x.`,a,'','ln er entydig for positive tall.',`x=${a}, som er positiv.`,Math.log(a),'Her skal du finne argumentet, ikke beregne logaritmen.');return result(`Løs ln(x−1) + ln(x+1) = ln(${a*a-1}). Finn x.`,a,'','Definisjonsmengden er x>1; bruk produktregelen.',`ln(x²−1)=ln(${a*a-1}) gir x²=${a*a}. Bare x=${a} oppfyller x>1.`, -a,'Den negative løsningen ligger utenfor definisjonsmengden.');}},
 {id:'invers',title:'Omvendte funksjoner og derivasjon',summary:'Undersøk inverse funksjoner og sammenhengen mellom de deriverte.',
 theory:['En funksjon har en omvendt funksjon på et område der den er entydig én-til-én. Grafene til f og f⁻¹ speiles om linjen y=x; definisjonsmengde og verdimengde bytter plass.','Hvis f er én-til-én og kontinuerlig deriverbar i et åpent intervall rundt a med f′(a)≠0, er (f⁻¹)′(f(a))=1/f′(a). For eksempel er eˣ og ln x inverse; (eˣ)′=eˣ og (ln x)′=1/x for x>0.'],example:['f(x)=x², x≥0, har invers f⁻¹(x)=√x, x≥0.','f(2)=4 og f′(2)=4, så (f⁻¹)′(4)=1/4. Dette stemmer med (√x)′=1/(2√x).'],activity:'Undersøk f(x)=x² på hele R og på [0,∞). Forklar når en invers eksisterer, finn den og tegn begge grafene. Sammenlign deriverte i tilhørende punkter og undersøk hva som skjer ved 0.',criteria:['Begrunner valg av definisjonsmengde.','Finner og kontrollerer inversen ved sammensetting.','Forklarer sammenhengen mellom deriverte og begrensningen ved 0.'],model:'På R er f ikke én-til-én siden f(−2)=f(2). På [0,∞) er inversen √x. f⁻¹(f(2))=2, og de deriverte i 2 og 4 er 4 og 1/4. Ved 0 har x² høyrederivert 0, mens √x har en vertikal tangent: høyre differansekvotient er 1/√h, som går mot uendelig.',teacher:'Skill mellom f⁻¹(x) og 1/f(x). Begrensningen f′≠0 er viktig.',goals:['Utforske, analysere og derivere funksjoner og deres omvendte funksjoner og forklare sammenhenger.'],
 task(level,seed){let a=n(seed,6,2),b=n(seed,5,1),x=n(seed,5,2);if(level===0)return result(`f(x)=${a}x+${b}. Finn f⁻¹(${a*x+b}).`,x,'','Finn x som gir den oppgitte funksjonsverdien.',`(${a*x+b}−${b})/${a}=${x}.`,a*x+b,'Dette er funksjonsverdien, ikke inversverdien.');if(level===1)return result(`f(x)=x² for x≥0. Finn (f⁻¹)′(${a*a}). Avrund til to desimaler.`,1/(2*a),'','Bruk inversderivert eller deriver √x.',`(f⁻¹)′(${a*a})=1/(2·${a})=${(1/(2*a)).toFixed(2)} avrundet.`,2*a,'Dette er f′ ved tilsvarende punkt; inversderivert er den resiproke.');return result(`f(x)=eˣ. Finn (f⁻¹)′(${a}). Avrund til to desimaler.`,1/a,'','Inversen er ln x.',`(ln x)′=1/x, så svaret er ${(1/a).toFixed(2)}.`,a,'Deriver ln x og sett inn argumentet.');}},
 {id:'vekstmodeller',source:'https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/Orange.html',dataset:{title:'Stammeomkrets for appelsintre 1 (Orange)',headers:['Døgn siden 31.12.1968','Stammeomkrets (mm)'],rows:[[118,30],[484,58],[664,87],[1004,115],[1231,120],[1372,142],[1582,145]]},title:'Eksponentiell og logistisk vekst',summary:'Modeller og analyser vekst med reelle datasett.',
 theory:['En eksponentiell modell N(t)=N₀eᵏᵗ har konstant relativ vekstfart N′/N=k. En logistisk modell N(t)=K/(1+ae⁻ᵏᵗ), med positive parametere, har bæreevne K og størst absolutt vekstfart ved N=K/2.','Modellparametere tilpasses data med digitale verktøy. Sammenlign residualer, forklar måleenheter og usikkerhet, og vurder om modellen kan ekstrapoleres. Et godt samsvar etablerer ikke årsak.'],example:['Reelle målinger fra datasettet Orange, tre 1: Tid siden 31.12.1968 i døgn og stammeomkrets i mm er (118, 30), (484, 58), (664, 87), (1004, 115), (1231, 120), (1372, 142) og (1582, 145). Kilde og dokumentasjon: https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/Orange.html (Draper og Smith, 1998).','La t være døgn siden første måling. En eksponentialmodell gjennom de to første punktene er $N(t)=30e^{kt}$, der $k=\\ln(58/30)/366\\approx 0{,}001801$ per døgn. For tredje måling er t=546, og modellen gir omtrent 80,21 mm mot observerte 87 mm. Modell minus observasjon er −6,79 mm.','Modellen har $N\\prime(t)=kN(t)$. Ved andre måling er den modellerte vekstfarten omtrent 0,104 mm/døgn. To punkter gir ikke grunnlag for å avgjøre om eksponentiell vekst er best; undersøk resten av datasettet.'],activity:'Planlegg og gjennomfør en selvstendig undersøkelse med et reelt naturvitenskapelig datasett, for eksempel Orange-måleserien i eksemplet eller en annen måleserie. Bruk hele den valgte dataserien. Oppgi kilde, tidsrom, enheter og metode. Tilpass eksponentiell og logistisk modell digitalt, sammenlign residualer og bruk de deriverte til å tolke vekstfart. Presenter funn og drøft modellvalg, usikkerhet og gyldighetsområde.',criteria:['Plan og datakilde gjør arbeidet etterprøvbart.','Begge modellene tilpasses og sammenlignes med residualer.','Deriverte tolkes med enheter; begrensninger og funn presenteres.'],model:'For Orange, tre 1, gir eksponentialmodellen gjennom de to første observasjonene 80,21 mm ved tredje måling mot 87 mm observert: residualen modell minus observasjon er −6,79 mm. Plott alle sju observasjoner og tilpass både eksponentiell og logistisk modell digitalt; sammenlign residualer og deriverte. Den viste topunktstilpasningen alene avgjør ikke hvilken modell som passer best.',teacher:'Vær oppmerksom på at et kort datasett kan gi ustabile estimater for logistisk bæreevne. Etterspør både tallgrunnlag og begrunnet kildevalg.',goals:['Planlegge, gjennomføre, analysere og presentere selvstendig arbeid med reelle naturvitenskapelige data.','Modellere og analysere eksponentiell og logistisk vekst i reelle datasett.','Bruke derivasjon til å analysere egne modeller av reelle data.'],
 task(level,seed){let a=n(seed,8,2)*10,k=n(seed,4,1)/10;if(level===0)return result(`N(t)=${a}e^(${k}t). Hva er N(0)?`,a,'','Sett t=0 og bruk e⁰=1.',`N(0)=${a}.`,a*k,'Dette er vekstfarten ved t=0.');if(level===1)return result(`N(t)=${a}e^(${k}t). Finn N′(0).`,a*k,'per tidsenhet','Deriver med kjerneregelen.',`N′(t)=${a*k}e^(${k}t), så N′(0)=${a*k}.`,a,'Dette er startverdien.');return result(`En logistisk modell er N(t)=${a*10}/(1+9e^(−${k}t)). Ved hvilken N er absolutt vekstfart størst?`,a*5,'','For en logistisk modell er veksten størst ved halv bæreevne.',`K=${a*10}; maksimal vekstfart oppstår ved N=K/2=${a*5}.`,a*10,'Bæreevnen er grenseverdien, ikke nivået med størst vekstfart.');}},
 {id:'vektorer',title:'Vektorer i planet',summary:'Regn med vektorer, lengde og skalarprodukt.',
 theory:['En vektor i planet har størrelse og retning og kan representeres ved koordinater [a,b]. Vektorer adderes koordinatvis, og multiplikasjon med en skalar endrer lengden og eventuelt retningen.','Lengden er √(a²+b²). Skalarproduktet u·v=u₁v₁+u₂v₂=|u||v|cos θ. For ikke-nullvektorer er skalarprodukt null akkurat når vektorene står vinkelrett.'],example:['A=(1,2) og B=(4,6) gir AB=[3,4] med lengde 5.','[3,4]·[4,−3]=12−12=0, så vektorene står normalt på hverandre.'],activity:'Undersøk trekanten A=(0,0), B=(4,0), C=(1,3). Finn sidelengdene, undersøk om noen vinkler er rette med skalarprodukt, og beregn arealet på to måter. Begrunn om trekanten er likebeint.',criteria:['Finner korrekte vektorer og lengder.','Bruker skalarprodukt og argumenterer om vinkler.','Kontrollerer arealet med to metoder.'],model:'AB=[4,0], AC=[1,3] og BC=[−3,3]. Lengdene er 4, √10 og √18, så trekanten er ikke likebeint. Skalarproduktene ved hjørnene er ikke null. Arealet er 4·3/2=6, også |4·3−0·1|/2=6.',teacher:'Skill mellom punkt og vektor, og merk at nullvektoren ikke har en bestemt retning.',goals:['Forstå vektorer og regneregler og bruke vektorer til å beregne størrelser i planet.'],
 task(level,seed){let a=n(seed,7,2),b=n(seed,7,2);if(level===0)return result(`u=[${a},${b}] og v=[2,3]. Finn førstekoordinaten til u+v.`,a+2,'','Legg sammen førstekoordinatene.',`${a}+2=${a+2}.`,b+3,'Dette er andrekoordinaten.');if(level===1)return result(`Finn skalarproduktet [${a},${b}] · [2,3].`,2*a+3*b,'','Multipliser samsvarende koordinater og summer.',`${a}·2+${b}·3=${2*a+3*b}.`,a+b,'Begge koordinatproduktene må være med.');return result(`u=[${a},${b}] og v=[${b},k]. Finn k slik at u og v står normalt på hverandre.`, -a,'','Sett skalarproduktet lik null.',`${a}·${b}+${b}k=0 gir k=−${a}.`,a,'Fortegnet må gjøre skalarproduktet null.');}},
 {id:'parameter',title:'Parameterframstillinger',summary:'Bruk linjer og bevegelse med vektorer.',
 theory:['En linje gjennom punktet P med retningsvektor v≠0 kan skrives r(t)=P+tv. Parameteren t gir posisjonen; koordinatene er hver sin funksjon av samme parameter.','For bevegelse kan t være tid, men parameteren trenger ikke alltid være tid. Skjæring mellom baner betyr ikke nødvendigvis kollisjon: da må begge objekter være på samme sted til samme tid.'],example:['r(t)=[1,2]+t[3,−1] gir x=1+3t og y=2−t. Ved t=2 er posisjonen (7,0).','Farten er lengden av hastighetsvektoren [3,−1], altså √10 lengdeenheter per tidsenhet dersom t er tid.'],activity:'To partikler har posisjoner r(t)=[0,0]+t[2,1] og s(t)=[6,0]+t[−1,1], t≥0. Finn om og når de møtes, stedet og hastighetene. Endre én startposisjon slik at banene skjærer hverandre uten samtidig møte, og begrunn forskjellen.',criteria:['Setter opp og løser begge koordinatlikningene med samme tid.','Finner posisjon og hastigheter med enheter.','Skiller mellom skjæring av baner og kollisjon.'],model:'2t=6−t gir t=2; y-koordinatene er begge 2. Møtestedet er (4,2). Hastighetsvektorene er [2,1] og [−1,1] lengdeenheter per tidsenhet. Fartene er √5 og √2. Endres s til [6,1]+t[−1,1], skjærer banene hverandre i (14/3,7/3), men tidene er 7/3 og 4/3.',teacher:'Kontroller både tidsbegrensning og begge koordinater. Skjæring med ulike parametere innebærer ikke kollisjon.',goals:['Anvende parameterframstillinger til linjer og naturvitenskapelige problemer.'],
 task(level,seed){let a=n(seed,7,2),t=n(seed,5,1);if(level===0)return result(`r(t)=[1,2]+t[${a},3]. Finn x-koordinaten ved t=${t}.`,1+a*t,'','Sett parameteren inn i x-uttrykket.',`x=1+${a}·${t}=${1+a*t}.`,2+3*t,'Dette er y-koordinaten.');if(level===1)return result(`r(t)=[1,2]+t[${a},3]. Finn t når x=${1+a*t}.`,t,'','Løs 1+at=x.',`t=(${1+a*t}−1)/${a}=${t}.`,(1+a*t)/a,'Trekk fra startkoordinaten først.');return result(`To partikler har x-koordinater x₁=${a}t og x₂=${a*t+t}−t og samme y-koordinat for alle t. Når møtes de?`,t,'tidsenheter','Sett x-koordinatene lik hverandre ved samme t.',`${a}t=${a*t+t}−t gir t=${t}.`,a*t+t,'Startavstanden er ikke møtetidspunktet.');}}
 ]};
